// ZIP STORE writer: UTF-8 paths, CRC32, no external dependencies.
export async function zip(entries){let enc=new TextEncoder(),locals=[],centrals=[],offset=0;let table=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});for(let [name,value]of entries){let b=value instanceof Blob?new Uint8Array(await value.arrayBuffer()):enc.encode(value),n=enc.encode(name),crc=0xffffffff;for(let x of b)crc=table[(crc^x)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;let l=new Uint8Array(30+n.length),v=new DataView(l.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,2048,true);v.setUint32(14,crc,true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,n.length,true);l.set(n,30);let c=new Uint8Array(46+n.length),w=new DataView(c.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,2048,true);w.setUint32(16,crc,true);w.setUint32(20,b.length,true);w.setUint32(24,b.length,true);w.setUint16(28,n.length,true);w.setUint32(42,offset,true);c.set(n,46);locals.push(l,b);centrals.push(c);offset+=l.length+b.length}let end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.length,true);v.setUint16(10,entries.length,true);v.setUint32(12,centrals.reduce((s,x)=>s+x.length,0),true);v.setUint32(16,offset,true);return new Blob([...locals,...centrals,end],{type:'application/zip'})}
